    "all": "सभी अलर्ट",
    "priority": "प्राथमिकता",
    "kpost_title_1": "जीवामृत से शून्य बजट प्राकृतिक खेती",
    "kpost_content_1": "10 किग्रा गोबर, 10 लीटर गोमूत्र, 2 किग्रा गुड़ और 2 किग्रा बेसन को 200 लीटर पानी में 48 घंटे किण्वित करके बना जीवामृत रासायनिक उर्वरकों का बेहतरीन विकल्प है। 2 सीजन में पैदावार 18% बढ़ी।",
    "kpost_title_2": "राइजोबियम बीजोपचार से लागत में 40% की कमी",
    "kpost_content_2": "सोयाबीन बीजों पर राइजोबियम जीवाणु संवर्धन से नाइट्रोजन उर्वरक की जरूरत खत्म हो जाती है। प्रति हेक्टेयर भारी बचत।",
    "kpost_title_3": "स्मार्ट ड्रिप सिंचाई गाइड — 35% पानी की बचत",
    "kpost_content_3": "मृदा नमी सेंसर लगाकर सिंचाई नियंत्रित करने से पानी का उपयोग 35% घटा और गेहूं की उपज 12% बढ़ी।",
    "kpost_title_4": "ठंड प्रतिरोधी सूरजमुखी किस्म का चयन",
    "kpost_content_4": "6 सीजन के चयन से तैयार सूरजमुखी संकर किस्म -5°C तापमान में भी बेहतर अंकुरण देती है।",
    "kpost_title_5": "पेड़ लगाकर 2 साल में मिट्टी का कायाकल्प",
    "kpost_content_5": "मक्का के खेतों के किनारों पर पेड़ लगाने से 24 महीनों में जैविक कार्बन 0.8% से बढ़कर 2.3% हो गया।",
    "kpost_title_6": "फेरोमोन ट्रैप से बिना कीटनाशक गुलाबी सूंडी नियंत्रण",
    "kpost_content_6": "प्रति एकड़ 8 फेरोमोन ट्रैप लगाने से सूंडी का प्रजनन चक्र टूट गया और बिना रसायन 70% नियंत्रण मिला।",
    "kpost_title_7": "बाढ़ के पानी में तैरती धान की खेती",
    "kpost_content_7": "पारंपरिक जैविक तैरते बगीचों की तर्ज पर धान उगाने से बिना सिंचाई लागत 2.9 टन/हेक्टेयर उपज मिली।",
    "kpost_title_8": "बायोचार से मिट्टी की जल धारण क्षमता 60% बढ़ी",
    "kpost_content_8": "धान की भूसी का बायोचार 5 टन/हेक्टेयर डालने से रेतीली मिट्टी में जल धारण क्षमता 60% बढ़ गई।",
