    "reasonRain": "{{rain}}% மழை பெய்ய வாய்ப்புள்ளது. உழவு மற்றும் அறுவடை செய்வததைத் தவிர்க்கவும்.",
    "reasonStress": "{{temperature}}° அதிக வெப்பநிலை மற்றும் {{uv}} UV அளவு பயிர்களை பாதிக்கலாம்.",
    "reasonHarvest": "{{condition}} வானிலை மற்றும் {{rain}}% மழை வாய்ப்பு அறுவடைக்கு மிகச் சிறந்த நேரமாகும்.",
    "coverCropAdvice": "அடுத்த பயிர் சுழற்சிக்கு முன் பருப்பு வகைகளை இடுவதன் மூலம் நைட்ரஜன் மற்றும் மண் வளத்தை மேம்படுத்தலாம்.",
    "irrigationHold": "மழை எதிர்பார்க்கப்படுகிறது—நீர்ப்பாசனத்தை நிறுத்தி, வடிகால் வசதியைச் சரிபார்க்கவும்.",
    "irrigationIncrease": "வறண்ட வானிலை நிலவக்கூடும்—அடுத்த 48 மணிநேரத்தில் கவனமாக நீர்ப்பாசனத்தை அதிகரிக்கவும்.",
