    "kpost_title_1": "जीवामृताने झिरो बजेट नैसर्गिक शेती",
    "kpost_content_1": "१० किलो शेण, १० लीटर गोमूत्र, २ किलो गूळ आणि २ किलो डाळीचे पीठ २०० लीटर पाण्यात ४८ तास आळवून तयार केलेले जीवामृत रासायनिक खतांना उत्तम पर्याय ठरते. दोन हंगामात उत्पादन १८% वाढले.",
    "kpost_title_2": "रायझोबियम बिजप्रक्रियेने खत खर्चात ४०% बचत",
    "kpost_content_2": "सोयाबीन पेरणीपूर्वी रायझोबियम जीवाणू संवर्धकाची प्रक्रिया केल्याने नत्र खतांची गरज उरत नाही. प्रति हेक्टरी मोठ्या प्रमाणात बचत होते.",
    "kpost_title_3": "स्मार्ट ठिबक सिंचन मार्गदर्शन — ३५% पाण्याची बचत",
    "kpost_content_3": "जमिनीतील ओलावा मोजणारे सेन्सर बसवून सिंचनाचे नियोजन केल्याने पाण्याचा वापर ३५% कमी झाला आणि गव्हाचे उत्पादन १२% वाढले.",
    "kpost_title_4": "थंडीस सहनशील सूर्यफूल वाणाची निवड",
    "kpost_content_4": "६ हंगाम निवडपद्धतीने तयार केलेले हे सूर्यफूल वाण उणे ५ अंश सेल्सिअस तापमानातही उत्तम उगवण क्षमता दाखवते.",
    "kpost_title_5": "अकॅशिया वृक्षलागवडीने २ वर्षांत जमिनीचा पोत सुधारला",
    "kpost_content_5": "मक्याच्या बांधावर अकॅशिया झाडे लावल्याने २४ महिन्यांत जमिनीतील सेंद्रिय कर्ब ०.८% वरून २.३% वर पोहोचला. उत्पादन १.८ वरून ३.१ टन प्रति हेक्टर झाले.",
    "kpost_title_6": "कामगंध सापळ्यांनी कीटकनाशकांशिवाय बोंडअळीचे नियंत्रण",
    "kpost_content_6": "एकरी ८ कामगंध सापळे लावल्याने बोंडअळीचे प्रजनन चक्र खंडित होऊन ७०% कीड नियंत्रण झाले.",
    "kpost_title_7": "पैलवान भात: पुराच्या पाण्यात तरंगती भातशेती",
    "kpost_content_7": "पाण्यात तरंगणाऱ्या बांबू व वनस्पतींच्या तराफ्यावर भातशेती करून सिंचन खर्चाशिवाय प्रति हेक्टरी २.९ टन उत्पादन मिळाले.",
    "kpost_title_8": "बायोचारच्या वापराने जमिनीची पाणी धरून ठेवण्याची क्षमता ६०% वाढली",
    "kpost_content_8": "तांदळाच्या तुसापासून बनवलेला बायोचार ५ टन प्रति हेक्टर वापरल्याने वालुकामय जमिनीत ६०% पाणी धरून ठेवण्याची क्षमता वाढली.",
